INSERT INTO `wp_aioseo_cache` VALUES (3,'addons','[{\"sku\":\"aioseo-eeat\",\"name\":\"Author SEO (E-E-A-T)\",\"version\":\"1.0.0\",\"image\":null,\"icon\":\"svg-eeat\",\"levels\":[\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Optimize your site for Google\'s E-E-A-T ranking factor by proving your writer\'s expertise through author schema markup and new UI elements.<\\/p>\",\"descriptionVersion\":0,\"productUrl\":\"https:\\/\\/aioseo.com\\/author-seo-eeat\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/author-seo-eeat\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-search-appearance:author-seo\",\"basename\":\"aioseo-eeat\\/aioseo-eeat.php\",\"installed\":false,\"isActive\":false,\"canInstall\":false,\"canActivate\":false,\"canUpdate\":false,\"capability\":\"aioseo_manage_seo\",\"minimumVersion\":\"0.0.0\",\"hasMinimumVersion\":false,\"featured\":300},{\"sku\":\"aioseo-link-assistant\",\"name\":\"Link Assistant\",\"version\":\"1.0.0\",\"image\":null,\"icon\":\"svg-link-assistant\",\"levels\":[\"agency\",\"pro\",\"elite\"],\"currentLevels\":[\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Super-charge your SEO with Link Assistant! Get relevant suggestions for adding internal links to older content as well as finding any orphaned posts that have no internal links. Use our reporting feature to see all link suggestions or add them directly from any page or post.<\\/p>\",\"descriptionVersion\":0,\"productUrl\":\"https:\\/\\/aioseo.com\\/feature\\/internal-link-assistant\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/feature\\/internal-link-assistant\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-link-assistant:overview\",\"basename\":\"aioseo-link-assistant\\/aioseo-link-assistant.php\",\"installed\":false,\"isActive\":false,\"canInstall\":false,\"canActivate\":false,\"canUpdate\":false,\"capability\":\"aioseo_manage_seo\",\"minimumVersion\":\"0.0.0\",\"hasMinimumVersion\":false,\"featured\":100},{\"sku\":\"aioseo-video-sitemap\",\"name\":\"Video Sitemap\",\"version\":\"1.0.0\",\"image\":null,\"icon\":\"svg-sitemaps-pro\",\"levels\":[\"individual\",\"business\",\"agency\",\"pro\",\"elite\"],\"currentLevels\":[\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>The Video Sitemap works in much the same way as the XML Sitemap module, it generates an XML Sitemap specifically for video content on your site. Search engines use this information to display rich snippet information in search results.<\\/p>\",\"descriptionVersion\":0,\"productUrl\":\"https:\\/\\/aioseo.com\\/video-sitemap\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/video-sitemap\",\"manageUrl\":\"https:\\/\\/route#aioseo-sitemaps:video-sitemap\",\"basename\":\"aioseo-video-sitemap\\/aioseo-video-sitemap.php\",\"installed\":false,\"isActive\":false,\"canInstall\":false,\"canActivate\":false,\"canUpdate\":false,\"capability\":\"aioseo_sitemap_settings\",\"minimumVersion\":\"0.0.0\",\"hasMinimumVersion\":false},{\"sku\":\"aioseo-local-business\",\"name\":\"Local Business SEO\",\"version\":\"1.0.0\",\"image\":null,\"icon\":\"svg-local-business\",\"levels\":[\"business\",\"agency\",\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Local Business schema markup enables you to tell Google about your business, including your business name, address and phone number, opening hours and price range. This information may be displayed as a Knowledge Graph card or business carousel.<\\/p>\",\"descriptionVersion\":0,\"productUrl\":\"https:\\/\\/aioseo.com\\/local-business\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/local-business\",\"manageUrl\":\"https:\\/\\/route#aioseo-local-seo:locations\",\"basename\":\"aioseo-local-business\\/aioseo-local-business.php\",\"installed\":false,\"isActive\":false,\"canInstall\":false,\"canActivate\":false,\"canUpdate\":false,\"capability\":\"aioseo_local_seo_settings\",\"minimumVersion\":\"0.0.0\",\"hasMinimumVersion\":false},{\"sku\":\"aioseo-news-sitemap\",\"name\":\"News Sitemap\",\"version\":\"1.0.0\",\"image\":null,\"icon\":\"svg-sitemaps-pro\",\"levels\":[\"business\",\"agency\",\"pro\",\"elite\"],\"currentLevels\":[\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Our Google News Sitemap lets you control which content you submit to Google News and only contains articles that were published in the last 48 hours. In order to submit a News Sitemap to Google, you must have added your site to Google\\u2019s Publisher Center and had it approved.<\\/p>\",\"descriptionVersion\":0,\"productUrl\":\"https:\\/\\/aioseo.com\\/news-sitemap\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/news-sitemap\",\"manageUrl\":\"https:\\/\\/route#aioseo-sitemaps:news-sitemap\",\"basename\":\"aioseo-news-sitemap\\/aioseo-news-sitemap.php\",\"installed\":false,\"isActive\":false,\"canInstall\":false,\"canActivate\":false,\"canUpdate\":false,\"capability\":\"aioseo_sitemap_settings\",\"minimumVersion\":\"0.0.0\",\"hasMinimumVersion\":false},{\"sku\":\"aioseo-index-now\",\"name\":\"IndexNow\",\"version\":\"1.0.0\",\"image\":null,\"icon\":\"svg-sitemaps-pro\",\"levels\":[\"agency\",\"business\",\"basic\",\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"basic\",\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Add IndexNow support to instantly notify search engines when your content has changed. This helps the search engines to prioritize the changes on your website and helps you rank faster.<\\/p>\",\"descriptionVersion\":0,\"downloadUrl\":\"\",\"productUrl\":\"https:\\/\\/aioseo.com\\/index-now\\/\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/index-now\\/\",\"manageUrl\":\"https:\\/\\/route#aioseo-settings:webmaster-tools\",\"basename\":\"aioseo-index-now\\/aioseo-index-now.php\",\"installed\":false,\"isActive\":false,\"canInstall\":false,\"canActivate\":false,\"canUpdate\":false,\"capability\":\"aioseo_general_settings\",\"minimumVersion\":\"0.0.0\",\"hasMinimumVersion\":false},{\"sku\":\"aioseo-image-seo\",\"name\":\"Image SEO\",\"version\":\"1.0.0\",\"image\":null,\"icon\":\"svg-image-seo\",\"levels\":[\"individual\",\"business\",\"agency\",\"plus\",\"pro\",\"elite\"],\"currentLevels\":[\"plus\",\"pro\",\"elite\"],\"requiresUpgrade\":true,\"description\":\"<p>Globally control the Title attribute and Alt text for images in your content. These attributes are essential for both accessibility and SEO.<\\/p>\",\"descriptionVersion\":0,\"productUrl\":\"https:\\/\\/aioseo.com\\/image-seo\",\"learnMoreUrl\":\"https:\\/\\/aioseo.com\\/image-seo\",\"manageUrl\":\"https:\\/\\/route#aioseo-search-appearance:media\",\"basename\":\"aioseo-image-seo\\/aioseo-image-seo.php\",\"installed\":false,\"isActive\":false,\"canInstall\":false,\"canActivate\":false,\"canUpdate\":false,\"capability\":\"aioseo_search_appearance_settings\",\"minimumVersion\":\"0.0.0\",\"hasMinimumVersion\":false}]',0,'2026-08-12 11:48:23','2026-08-09 01:33:38','2026-08-11 11:48:23'),(4,'db_schema','{\"wp_actionscheduler_actions\":[\"action_id\",\"hook\",\"status\",\"scheduled_date_gmt\",\"scheduled_date_local\",\"priority\",\"args\",\"schedule\",\"group_id\",\"attempts\",\"last_attempt_gmt\",\"last_attempt_local\",\"claim_id\",\"extended_args\"],\"wp_actionscheduler_claims\":[\"claim_id\",\"date_created_gmt\"],\"wp_actionscheduler_groups\":[\"group_id\",\"slug\"],\"wp_actionscheduler_logs\":[\"log_id\",\"action_id\",\"message\",\"log_date_gmt\",\"log_date_local\"],\"wp_aioseo_ai_insights_keyword_reports\":[\"id\",\"uuid\",\"keyword\",\"status\",\"brands\",\"brands_mentioned\",\"results\",\"created\",\"updated\"],\"wp_aioseo_cache\":[\"id\",\"name\",\"value\",\"is_object\",\"expiration\",\"created\",\"updated\"],\"wp_aioseo_crawl_cleanup_blocked_args\":[\"id\",\"param\",\"value\",\"param_value_hash\",\"regex\",\"hits\",\"created\",\"updated\"],\"wp_aioseo_crawl_cleanup_logs\":[\"id\",\"slug\",\"param\",\"value\",\"hash\",\"hits\",\