LOCK TABLES `wp_posts` WRITE;
/*!40000 ALTER TABLE `wp_posts` DISABLE KEYS */;
INSERT INTO `wp_posts` VALUES (1,1,'2026-08-09 01:07:15','2026-08-09 01:07:15','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','trash','open','open','','hello-world__trashed','','','2026-08-11 23:24:20','2026-08-11 15:24:20','',0,'http://modafinil-malaysia.test/?p=1',0,'post','',1),(2,1,'2026-08-09 01:07:15','2026-08-09 01:07:15','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://modafinil-malaysia.test/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','trash','closed','open','','sample-page__trashed','','','2026-08-11 22:06:04','2026-08-11 14:06:04','',0,'http://modafinil-malaysia.test/?page_id=2',0,'page','',0),(3,1,'2026-08-09 01:07:15','2026-08-09 01:07:15','','Privacy Policy','','trash','closed','open','','privacy-policy__trashed','','','2026-08-12 01:35:40','2026-08-11 17:35:40','',0,'http://modafinil-malaysia.test/?page_id=3',0,'page','',0),(4,0,'2026-08-09 01:07:29','2026-08-09 01:07:29','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-08-09 01:07:29','2026-08-09 01:07:29','',0,'http://modafinil-malaysia.test/2026/08/09/navigation/',0,'wp_navigation','',0),(5,0,'2026-08-09 01:07:29','2026-08-09 01:07:29','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-08-09 01:07:29','2026-08-09 01:07:29','',0,'http://modafinil-malaysia.test/index.php/2026/08/09/navigation/',0,'wp_navigation','',0),(6,1,'2026-08-09 01:10:28','0000-00-00 00:00:00','','Auto Draft','','auto-draft','open','open','','','','','2026-08-09 01:10:28','0000-00-00 00:00:00','',0,'http://modafinil-malaysia.test/?p=6',0,'post','',0),(8,1,'2026-08-09 09:42:17','2026-08-09 01:42:17','','Homepage','','publish','closed','closed','','homepage','','','2026-08-12 01:58:01','2026-08-11 17:58:01','',0,'http://modafinil-malaysia.test/homepage/',0,'page','',0),(9,1,'2026-08-09 09:47:09','2026-08-09 01:47:09','','woocommerce-placeholder','','inherit','open','closed','','woocommerce-placeholder','','','2026-08-09 09:47:09','2026-08-09 01:47:09','',0,'http://modafinil-malaysia.test/wp-content/uploads/2026/08/woocommerce-placeholder.webp',0,'attachment','image/webp',0),(10,1,'2026-08-09 09:47:11','2026-08-09 01:47:11','','Shop','','publish','closed','closed','','shop','','','2026-08-11 22:49:40','2026-08-11 14:49:40','',0,'http://modafinil-malaysia.test/shop/',0,'page','',0),(11,1,'2026-08-09 09:47:11','2026-08-09 01:47:11','[woocommerce_cart]','Cart','','publish','closed','closed','','cart','','','2026-08-12 03:00:19','2026-08-11 19:00:19','',0,'http://modafinil-malaysia.test/cart/',0,'page','',0),(12,1,'2026-08-09 09:47:11','2026-08-09 01:47:11','[woocommerce_checkout]','Checkout','','publish','closed','closed','','checkout','','','2026-08-12 02:59:44','2026-08-11 18:59:44','',0,'http://modafinil-malaysia.test/checkout/',0,'page','',0),(13,1,'2026-08-09 09:47:11','2026-08-09 01:47:11','<!-- wp:shortcode -->[woocommerce_my_account]<!-- /wp:shortcode -->','My account','','publish','closed','closed','','my-account','','','2026-08-09 09:47:11','2026-08-09 01:47:11','',0,'http://modafinil-malaysia.test/my-account/',0,'page','',0),(14,1,'2026-08-09 09:47:11','0000-00-00 00:00:00','<!-- wp:paragraph -->\n<p><b>This is a sample page.</b></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Overview</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our refund and returns policy lasts 30 days. If 30 days have passed since your purchase, we can’t offer you a full refund or exchange.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>To be eligible for a return, your item must be unused and in the same condition that you received it. It must also be in the original packaging.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Several types of goods are exempt from being returned. Perishable goods such as food, flowers, newspapers or magazines cannot be returned. We also do not accept products that are intimate or sanitary goods, hazardous materials, or flammable liquids or gases.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Additional non-returnable items:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Gift cards</li>\n<li>Downloadable software products</li>\n<li>Some health and personal care items</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>To complete your return, we require a receipt or proof of purchase.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Please do not send your purchase back to the manufacturer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There are certain situations where only partial refunds are granted:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Book with obvious signs of use</li>\n<li>CD, DVD, VHS tape, software, video game, cassette tape, or vinyl record that has been opened.</li>\n<li>Any item not in its original condition, is damaged or missing parts for reasons not due to our error.</li>\n<li>Any item that is returned more than 30 days after delivery</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Refunds</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Once your return is received and inspected, we will send you an email to notify you that we have received your returned item. We will also notify you of the approval or rejection of your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are approved, then your refund will be processed, and a credit will automatically be applied to your credit card or original method of payment, within a certain amount of days.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Late or missing refunds</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you haven’t received a refund yet, first check your bank account again.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Then contact your credit card company, it may take some time before your refund is officially posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Next contact your bank. There is often some processing time before a refund is posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you’ve done all of this and you still have not received your refund yet, please contact us at {email address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sale items</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Only regular priced items may be refunded. Sale items cannot be refunded.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Exchanges</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We only replace items if they are defective or damaged. If you need to exchange it for the same item, send us an email at {email address} and send your item to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Gifts</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If the item was marked as a gift when purchased and shipped directly to you, you’ll receive a gift credit for the value of your return. Once the returned item is received, a gift certificate will be mailed to you.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If the item wasn’t marked as a gift when purchased, or the gift giver had the order shipped to themselves to give to you later, we will send a refund to the gift giver and they will find out about your return.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Shipping returns</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>To return your product, you should mail your product to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You will be responsible for paying for your own shipping costs for returning your item. Shipping costs are non-refundable. If you receive a refund, the cost of return shipping will be deducted from your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Depending on where you live, the time it may take for your exchanged product to reach you may vary.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are returning more expensive items, you may consider using a trackable shipping service or purchasing shipping insurance. We don’t guarantee that we will receive your returned item.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Need help?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Contact us at {email} for questions related to refunds and returns.</p>\n<!-- /wp:paragraph -->','Refund and Returns Policy','','draft','closed','closed','','refund_returns','','','2026-08-09 09:47:11','0000-00-00 00:00:00','',0,'http://modafinil-malaysia.test/?page_id=14',0,'page','',0),(15,1,'2026-08-09 09:47:51','2026-08-09 01:47:51','{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }','Custom Styles','','publish','closed','closed','','wp-global-styles-modafinil-malaysia-wp','','','2026-08-09 09:47:51','2026-08-09 01:47:51','',0,'http://modafinil-malaysia.test/wp-global-styles-modafinil-malaysia-wp/',0,'wp_global_styles','',0),(16,1,'2026-08-09 09:51:22','0000-00-00 00:00:00','','','','auto-draft','closed','closed','','','','','2026-08-09 09:51:22','0000-00-00 00:00:00','',0,'http://modafinil-malaysia.test/?post_type=acf-field-group&p=16',0,'acf-field-group','',0),(17,1,'2026-08-09 09:51:28','0000-00-00 00:00:00','','','','auto-draft','closed','closed','','','','','2026-08-09 09:51:28','0000-00-00 00:00:00','',0,'http://modafinil-malaysia.test/?post_type=acf-field-group&p=17',0,'acf-field-group','',0),(19,1,'2026-08-09 23:40:51','2026-08-09 15:40:51','a:17:{s:10:\"aria-label\";s:0:\"\";s:4:\"type\";s:5:\"image\";s:12:\"instructions\";s:0:\"\";s:8:\"required\";i:0;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:13:\"return_format\";s:2:\"id\";s:7:\"library\";s:3:\"all\";s:9:\"min_width\";s:0:\"\";s:10:\"min_height\";s:0:\"\";s:8:\"min_size\";s:0:\"\";s:9:\"max_width\";s:0:\"\";s:10:\"max_height\";s:0:\"\";s:8:\"max_size\";s:0:\"\";s:10:\"mime_types\";s:0:\"\";s:17:\"allow_in_bindings\";i:0;s:12:\"preview_size\";s:6:\"medium\";}','Top Image','top_image','publish','closed','closed','','field_6970d0396a107','','','2026-08-09 23:40:51','2026-08-09 15:40:51','',18,'http://modafinil-malaysia.test/?post_type=acf-field&p=19',0,'acf-field','',0),(21,1,'2026-08-09 23:40:51','2026-08-09 15:40:51','a:12:{s:10:\"aria-la